//! Deterministic SVG and machine-readable specification rendering.

use std::fmt::Write as _;

use crate::color::Paint;
use crate::color::Palette;
use crate::glyph::Circle;
use crate::glyph::GlyphGeometry;
use crate::model::GearModel;
use crate::model::Point;

pub(crate) fn render_fixed(model: &GearModel, palette: &Palette, ground: &str) -> String {
    render_svg(model, fixed_style(palette), ground)
}

pub(crate) fn render_adaptive(model: &GearModel, light: &Palette, dark: &Palette) -> String {
    let style = format!(
        ".primary{{stroke:{}}}.accent{{stroke:{}}}.accent-fill{{fill:{}}}\
         .signal{{fill:{}}}.guide{{stroke:{}}}\n\
         @media(prefers-color-scheme:dark){{.primary{{stroke:{}}}.accent{{stroke:{}}}\
         .accent-fill{{fill:{}}}.signal{{fill:{}}}.guide{{stroke:{}}}}}",
        light.primary.hex,
        light.accent.hex,
        light.accent.hex,
        light.signal.hex,
        light.guide.hex,
        dark.primary.hex,
        dark.accent.hex,
        dark.accent.hex,
        dark.signal.hex,
        dark.guide.hex,
    );
    render_svg(model, style, "adaptive background")
}

