fn embedded_logo(model: &GearModel, palette: &Palette) -> String {
    let radius = viewbox_radius(model);
    let size = 2.0 * radius;
    format!(
        "  <svg x=\"100\" y=\"96\" width=\"88\" height=\"88\" viewBox=\"-{} -{} {} {}\">\n\
         <style>{}</style><defs><path id=\"tooth\" d=\"{}\"/></defs>\n{}</svg>",
        format_number(radius),
        format_number(radius),
        format_number(size),
        format_number(size),
        fixed_style(palette),
        tooth_path(model),
        geometry_fragment(model),
    )
}

fn fixed_style(palette: &Palette) -> String {
    format!(
        ".primary{{stroke:{}}}.accent{{stroke:{}}}.accent-fill{{fill:{}}}\
         .signal{{fill:{}}}.guide{{stroke:{}}}",
        palette.primary.hex,
        palette.accent.hex,
        palette.accent.hex,
        palette.signal.hex,
        palette.guide.hex,
    )
}

fn render_svg(model: &GearModel, style: String, ground: &str) -> String {
    let tooth = tooth_path(model);
    let geometry = geometry_fragment(model);
    let radius = viewbox_radius(model);
    let size = format_number(2.0 * radius);
    format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1024\" height=\"1024\" \
         viewBox=\"-{} -{} {size} {size}\" role=\"img\" aria-labelledby=\"title desc\">\n\
         <title id=\"title\">Rings geometric construction mark, {ground}</title>\n\
         <desc id=\"desc\">A thirty-tooth involute gear, five bores on a regular pentagon, \
         construction circles, and a nine-module Pacioli-derived R.</desc>\n\
         <metadata>{}</metadata>\n<style>{style}</style>\n\
         <defs><path id=\"tooth\" d=\"{tooth}\"/></defs>\n{geometry}</svg>\n",
        format_number(radius),
        format_number(radius),
        metadata(model),
    )
}

fn geometry_fragment(model: &GearModel) -> String {
    let module = model.spec.module;
    let holes = f64::from(model.spec.hole_count);
    let mut output = String::new();
    let _ = writeln!(
        output,
        "<g class=\"guide\" fill=\"none\" stroke-width=\"{}\">",
        format_number(model.construction_guide_width),
    );
    let _ = writeln!(
        output,
        "  <path d=\"M -{} 0 H {} M 0 -{} V {}\"/>",
        format_number(model.outer_radius + module),
        format_number(model.outer_radius + module),
        format_number(model.outer_radius + module),
        format_number(model.outer_radius + module),
    );
    let _ = writeln!(
        output,
        "  <circle r=\"{}\"/>",
        format_number(model.outer_radius)
    );
    append_circle(
        &mut output,
        model.pitch_radius,
        module * (holes - 3.0) / holes,
        module / 2.0,
    );
    append_circle(&mut output, model.base_radius, module / holes, module / 2.0);
    append_circle(
        &mut output,
        model.root_radius,
        module * (holes - 1.0) / holes,
        module * (holes - 3.0) / holes,
    );
    let _ = writeln!(
        output,
        "  <circle r=\"{}\"/>",
        format_number(model.aperture_radius)
    );
    append_circle(
        &mut output,
        model.hole_orbit,
        module * (holes - 2.0) / holes,
        module / 2.0,
    );
    let _ = writeln!(output, "  <polygon points=\"{}\"/>", polygon_points(model));
    let phase = GearModel::point(model.outer_radius, -std::f64::consts::PI / 2.0);
    let _ = writeln!(output, "  <path d=\"M 0 0 L {}\"/>", command_point(phase));
    append_glyph_guides(&mut output, model.glyph());
    output.push_str("</g>\n");

    let _ = writeln!(
        output,
        "<g class=\"primary\" fill=\"none\" stroke-width=\"{}\" stroke-linecap=\"square\" stroke-linejoin=\"miter\">",
        format_number(model.gear_outline_width),
    );
    for tooth in 0..model.spec.teeth {
        let rotation = 360.0 * f64::from(tooth) / f64::from(model.spec.teeth);
        let _ = writeln!(
            output,
            "  <use href=\"#tooth\" transform=\"rotate({})\"/>",
            format_number(rotation)
        );
    }
    output.push_str("</g>\n");

    let _ = writeln!(
        output,
        "<g class=\"accent\" fill=\"none\" stroke-width=\"{}\" stroke-linecap=\"butt\" stroke-linejoin=\"miter\">",
        format_number(model.gear_outline_width),
    );
    for hole in model.holes() {
        let _ = writeln!(
            output,
            "  <circle cx=\"{}\" cy=\"{}\" r=\"{}\"/>",
            format_number(hole.x),
            format_number(hole.y),
            format_number(model.hole_radius),
        );
    }
    output.push_str("</g>\n");
    append_glyph(&mut output, model.glyph());
    output.push_str("<g class=\"signal\">\n");
    for hole in model.holes() {
        let _ = writeln!(
            output,
            "  <circle cx=\"{}\" cy=\"{}\" r=\"{}\"/>",
            format_number(hole.x),
            format_number(hole.y),
            format_number(model.hole_radius / holes),
        );
    }
    output.push_str("</g>\n");
    output
}

fn append_circle(output: &mut String, radius: f64, dash: f64, gap: f64) {
    let _ = writeln!(
        output,
        "  <circle r=\"{}\" stroke-dasharray=\"{} {}\"/>",
        format_number(radius),
        format_number(dash),
        format_number(gap),
    );
}

fn append_glyph_guides(output: &mut String, glyph: GlyphGeometry) {
    let side = 2.0 * glyph.square_half;
    let guide_opacity = glyph.thin_stroke_width / glyph.stroke_width;
    let _ = writeln!(output, "  <g opacity=\"{}\">", format_number(guide_opacity));
    let _ = writeln!(
        output,
        "    <rect x=\"-{}\" y=\"-{}\" width=\"{}\" height=\"{}\"/>",
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(side),
        format_number(side),
    );
    let _ = writeln!(
        output,
        "    <path d=\"M -{} 0 H {} M -{} -{} L {} {} M -{} {} L {} -{} \
         M {} L {} M {} L {}\"/>",
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        format_number(glyph.square_half),
        command_point(glyph.leg.diagonal_start),
        command_point(glyph.leg.outer_circle.center),
        command_point(glyph.leg.outer_circle.center),
        command_point(glyph.leg.outer_end),
    );
    for circle in glyph_construction_circles(glyph) {
        append_positioned_circle(output, circle, "    ");
    }
    output.push_str("  </g>\n");
}

fn glyph_construction_circles(glyph: GlyphGeometry) -> [Circle; 5] {
    [
        glyph.bowl.outer,
        glyph.bowl.inner,
        glyph.serifs.top_left.circle,
        glyph.serifs.bottom_left.circle,
        glyph.serifs.bottom_inner.circle,
    ]
}

fn append_positioned_circle(output: &mut String, circle: Circle, indent: &str) {
    let _ = writeln!(
        output,
        "{indent}<circle cx=\"{}\" cy=\"{}\" r=\"{}\"/>",
        format_number(circle.center.x),
        format_number(circle.center.y),
        format_number(circle.radius),
    );
}

fn append_glyph(output: &mut String, glyph: GlyphGeometry) {
    let _ = writeln!(
        output,
        "<g class=\"accent-fill\" stroke=\"none\" fill-rule=\"evenodd\">"
    );
    let _ = writeln!(output, "  <path d=\"{}\"/>", glyph_path(glyph));
    output.push_str("</g>\n");
}

fn glyph_path(glyph: GlyphGeometry) -> String {
    format!("{} {}", outer_silhouette_path(glyph), counter_path(glyph))
}

fn outer_silhouette_path(glyph: GlyphGeometry) -> String {
    let leg = glyph.leg;
    let inner = leg.inner;
    let top = glyph.serifs.top_left;
    let bottom_left = glyph.serifs.bottom_left;
    let bottom_inner = glyph.serifs.bottom_inner;
    format!(
        "M {} A {} {} 0 0 1 {} A {} {} 0 0 0 {} A {} {} 0 0 0 {} \
         A {} {} 0 0 1 {} L {} A {} {} 0 0 1 {} H {} V {} \
         A {} {} 0 0 0 {} H {} A {} {} 0 0 0 {} V {} \
         A {} {} 0 0 0 {} H -{} H {} Z",
        command_point(glyph.bowl.outer_top),
        format_number(glyph.bowl.outer.radius),
        format_number(glyph.bowl.outer.radius),
        command_point(leg.outer_start),
        format_number(leg.outer_rounding_circle.radius),
        format_number(leg.outer_rounding_circle.radius),
        command_point(leg.outer_join),
        format_number(leg.outer_circle.radius),
        format_number(leg.outer_circle.radius),
        command_point(inner.tip),
        format_number(inner.tip_circle.radius),
        format_number(inner.tip_circle.radius),
        command_point(inner.tip_tangent),
        command_point(inner.root_tangent),
        format_number(inner.root_circle.radius),
        format_number(inner.root_circle.radius),
        command_point(inner.root),
        format_number(glyph.stem.right),
        format_number(bottom_inner.stem_tangent.y),
        format_number(bottom_inner.circle.radius),
        format_number(bottom_inner.circle.radius),
        command_point(bottom_inner.edge_tangent),
        format_number(bottom_left.edge_tangent.x),
        format_number(bottom_left.circle.radius),
        format_number(bottom_left.circle.radius),
        command_point(bottom_left.stem_tangent),
        format_number(top.stem_tangent.y),
        format_number(top.circle.radius),
        format_number(top.circle.radius),
        command_point(top.edge_tangent),
        format_number(glyph.square_half),
        format_number(glyph.bowl.outer_top.x),
    )
}

fn counter_path(glyph: GlyphGeometry) -> String {
    format!(
        "M {},{} H {} A {} {} 0 0 1 {} H {} Z",
        format_number(glyph.stem.right),
        format_number(glyph.bowl.inner_top.y),
        format_number(glyph.bowl.inner_top.x),
        format_number(glyph.bowl.inner.radius),
        format_number(glyph.bowl.inner.radius),
        command_point(glyph.bowl.counter_bottom),
        format_number(glyph.stem.right),
    )
}

fn tooth_path(model: &GearModel) -> String {
    let center = -std::f64::consts::PI / 2.0;
    let left_root = GearModel::point(model.root_radius, center - model.flank_rotation);
    let left_base = GearModel::point(model.base_radius, center - model.flank_rotation);
    let mut commands = format!(
        "M {} L {}",
        command_point(left_root),
        command_point(left_base)
    );

    for sample in 1..=model.flank_samples {
        let parameter =
            model.outer_involute_parameter * f64::from(sample) / f64::from(model.flank_samples);
        let (radius, angle) = model.polar_involute(parameter);
        let point = GearModel::point(radius, center - model.flank_rotation + angle);
        let _ = write!(commands, " L {}", command_point(point));
    }

    let (_, outer_angle) = model.polar_involute(model.outer_involute_parameter);
    let right_tip = GearModel::point(
        model.outer_radius,
        center + model.flank_rotation - outer_angle,
    );
    let _ = write!(
        commands,
        " A {} {} 0 0 1 {}",
        format_number(model.outer_radius),
        format_number(model.outer_radius),
        command_point(right_tip),
    );

    for sample in (0..model.flank_samples).rev() {
        let parameter =
            model.outer_involute_parameter * f64::from(sample) / f64::from(model.flank_samples);
        let (radius, angle) = model.polar_involute(parameter);
        let point = GearModel::point(radius, center + model.flank_rotation - angle);
        let _ = write!(commands, " L {}", command_point(point));
    }

    let right_root = GearModel::point(model.root_radius, center + model.flank_rotation);
    let next_left_root = GearModel::point(
        model.root_radius,
        center + model.tooth_pitch - model.flank_rotation,
    );
    let _ = write!(
        commands,
        " L {} A {} {} 0 0 1 {}",
        command_point(right_root),
        format_number(model.root_radius),
        format_number(model.root_radius),
        command_point(next_left_root),
    );
    commands
}

fn polygon_points(model: &GearModel) -> String {
    model
        .holes()
        .map(command_point)
        .collect::<Vec<_>>()
        .join(" ")
}

fn command_point(point: Point) -> String {
    format!("{},{}", format_number(point.x), format_number(point.y))
}

fn metadata(model: &GearModel) -> String {
    let glyph = model.glyph();
    format!(
        "module={};teeth={};pressure-angle={}deg;pitch-radius={};base-radius={};\
         outer-radius={};root-radius={};aperture-radius={};bore-count={};\
         bore-orbit={};bore-radius={};r-stroke={};gear-stroke={};guide-stroke={};\
         r-square-side={};r-unit={};r-thin-stroke={};r-bowl-outer-radius={};\
         r-bowl-inner-radius={};\
         r-serif-radius={};r-leg-outer=diagonal-chord-circle;sagitta={};\
         r-leg-outer-rounding-radius={};r-glyph-fill=one-outer-silhouette-plus-counter;\
         r-leg-root-radius={};r-leg-tip-radius={};\
         r-leg-inner=two-tangent-arcs-plus-3-4-5-line;\
         r-method=pacioli-nine-part-square-plus-rings-explicit-completion",
        format_number(model.spec.module),
        model.spec.teeth,
        format_number(model.spec.pressure_angle_degrees),
        format_number(model.pitch_radius),
        format_number(model.base_radius),
        format_number(model.outer_radius),
        format_number(model.root_radius),
        format_number(model.aperture_radius),
        model.spec.hole_count,
        format_number(model.hole_orbit),
        format_number(model.hole_radius),
        format_number(glyph.stroke_width),
        format_number(model.gear_outline_width),
        format_number(model.construction_guide_width),
        format_number(2.0 * glyph.square_half),
        format_number(glyph.unit),
        format_number(glyph.thin_stroke_width),
        format_number(glyph.bowl.outer.radius),
        format_number(glyph.bowl.inner.radius),
        format_number(glyph.serifs.top_left.circle.radius),
        format_number(glyph.leg.outer_sagitta),
        format_number(glyph.leg.outer_rounding_circle.radius),
        format_number(glyph.leg.inner.root_circle.radius),
        format_number(glyph.leg.inner.tip_circle.radius),
    )
}

fn viewbox_radius(model: &GearModel) -> f64 {
    model.outer_radius + 2.0 * model.hole_radius
}

pub(crate) fn render_specification(model: &GearModel, light: &Palette, dark: &Palette) -> String {
    let glyph = model.glyph();
    format!(
        "{{\n  \"generator\": \"rings-logo\",\n  \"geometry\": {{\n    \"module\": {},\n    \"teeth\": {},\n    \"pressure_angle_degrees\": {},\n    \"pitch_radius\": {},\n    \"base_radius\": {},\n    \"outer_radius\": {},\n    \"root_radius\": {},\n    \"aperture_radius\": {},\n    \"bore_count\": {},\n    \"bore_orbit\": {},\n    \"bore_radius\": {},\n    \"teeth_per_bore_sector\": {},\n    \"flank_samples\": {}\n  }},\n  \"geometry_rules\": {{\n    \"aperture_radius\": \"2*bore_count*module\",\n    \"bore_orbit\": \"aperture_radius+2*module\",\n    \"bore_radius\": \"(bore_count-1)/bore_count*module\",\n    \"flank_samples\": \"teeth/bore_count*(bore_count-1)\",\n    \"viewbox_radius\": \"outer_radius+2*bore_radius\",\n    \"gear_outline_width\": \"r_stroke/teeth_per_bore_sector\",\n    \"construction_guide_width\": \"gear_outline_width/bore_count\"\n  }},\n  \"glyph\": {{\n    \"mother_square_side\": {},\n    \"unit\": {},\n    \"dominant_stroke\": {},\n    \"fine_stroke\": {},\n    \"bowl_outer_radius\": {},\n    \"bowl_inner_radius\": {},\n    \"serif_circle_radius\": {},\n    \"leg_outer_circle_radius\": {},\n    \"leg_outer_sagitta\": {},\n    \"leg_outer_rounding_radius\": {},\n    \"leg_outer_root\": [{}, {}],\n    \"leg_outer_rounding_center\": [{}, {}],\n    \"leg_outer_join\": [{}, {}],\n    \"leg_root_arc_radius\": {},\n    \"leg_tip_arc_radius\": {},\n    \"leg_root\": [{}, {}],\n    \"leg_root_tangent\": [{}, {}],\n    \"leg_tip_tangent\": [{}, {}],\n    \"leg_tip\": [{}, {}]\n  }},\n  \"glyph_rules\": {{\n    \"historical_base\": {{\n      \"method\": \"R derived from B\",\n      \"mother_square\": \"side L divided into nine modules\",\n      \"dominant_stroke\": \"u=L/9\",\n      \"fine_stroke\": \"u/2=L/18\",\n      \"b_round\": \"paired circular contours; lower diameter 5L/9\",\n      \"serifs\": \"brackets constructed by tangent circles\",\n      \"leg_outer\": \"circular arc from square center to lower-right corner\",\n      \"leg_inner\": \"straight segment joined to two tangent circular arcs\",\n      \"leg_root_width\": \"approximately L/9; both sides taper to zero at the corner\"\n    }},\n    \"rings_completion\": {{\n      \"scope\": \"parameters not fully specified by the surviving Pacioli plate\",\n      \"square_binding\": \"L=sqrt(2)*aperture_radius\",\n      \"stem_edges\": \"left=-19u/6; right=-13u/6\",\n      \"bowl_outer\": \"center=(-u/2,-17u/8); radius=19u/8\",\n      \"bowl_inner\": \"center=(-5u/4,-17u/8); radius=17u/8\",\n      \"serif_circle_radius\": \"2u/3\",\n      \"leg_root\": \"S=(-u/2,0), on the crossbar; CS=u/2\",\n      \"leg_root_arc\": \"center=(-u/2,13u/64); radius=13u/64; tangent to the crossbar at S\",\n      \"leg_straight\": \"x=3y/4-29u/32; direction is the 3-4-5 triangle\",\n      \"leg_outer_arc\": \"support circle passes through C and D with sagitta u/10; visible arc begins at the derived tangent T\",\n      \"leg_outer_root\": \"B=bowl outer waist; BS=3sqrt(2)u/4\",\n      \"leg_outer_rounding\": \"n=(B-O_b)/r_b; r_o=(R^2-|B-O|^2)/(2(R+(B-O) dot n)); center=B+r_o*n; tangent=T=O+R(center-O)/|center-O|\",\n      \"glyph_fill\": \"one continuous outer silhouette plus one counter; no component closure crosses the bowl-leg junction\",\n      \"leg_root_radius\": \"13u/64; line tangency=(-53u/80,13u/40)\",\n      \"leg_tip_radius\": \"17833u/3328; line tangency=(143u/160,12u/5)\",\n      \"leg_tip\": \"tip arc passes through D=(9u/2,9u/2); both contours meet at D\"\n    }}\n  }},\n  \"color_rules\": {{\n    \"space\": \"OKLCH converted to quantized sRGB\",\n    \"lightness_grid\": \"1/10000\",\n    \"rust_hue\": \"360/(2*bore_count)=36deg\",\n    \"signal_hue\": \"rust_hue+180=216deg\",\n    \"accent_chroma\": \"(bore_count-1)/teeth\",\n    \"guide_chroma\": \"1/teeth\",\n    \"neutral_chroma\": \"guide_chroma/pentagonal_golden_ratio^2\"\n  }},\n  \"palettes\": {{\n    \"light_background\": {},\n    \"dark_background\": {}\n  }}\n}}\n",
        format_number(model.spec.module),
        model.spec.teeth,
        format_number(model.spec.pressure_angle_degrees),
        format_number(model.pitch_radius),
        format_number(model.base_radius),
        format_number(model.outer_radius),
        format_number(model.root_radius),
        format_number(model.aperture_radius),
        model.spec.hole_count,
        format_number(model.hole_orbit),
        format_number(model.hole_radius),
        model.teeth_per_bore_sector(),
        model.flank_samples,
        format_number(2.0 * glyph.square_half),
        format_number(glyph.unit),
        format_number(glyph.stroke_width),
        format_number(glyph.thin_stroke_width),
        format_number(glyph.bowl.outer.radius),
        format_number(glyph.bowl.inner.radius),
        format_number(glyph.serifs.top_left.circle.radius),
        format_number(glyph.leg.outer_circle.radius),
        format_number(glyph.leg.outer_sagitta),
        format_number(glyph.leg.outer_rounding_circle.radius),
        format_number(glyph.leg.outer_start.x),
        format_number(glyph.leg.outer_start.y),
        format_number(glyph.leg.outer_rounding_circle.center.x),
        format_number(glyph.leg.outer_rounding_circle.center.y),
        format_number(glyph.leg.outer_join.x),
        format_number(glyph.leg.outer_join.y),
        format_number(glyph.leg.inner.root_circle.radius),
        format_number(glyph.leg.inner.tip_circle.radius),
        format_number(glyph.leg.inner.root.x),
        format_number(glyph.leg.inner.root.y),
        format_number(glyph.leg.inner.root_tangent.x),
        format_number(glyph.leg.inner.root_tangent.y),
        format_number(glyph.leg.inner.tip_tangent.x),
        format_number(glyph.leg.inner.tip_tangent.y),
        format_number(glyph.leg.inner.tip.x),
        format_number(glyph.leg.inner.tip.y),
        palette_json(light),
        palette_json(dark),
    )
}

fn palette_json(palette: &Palette) -> String {
    format!(
        "{{\n      \"primary\": {},\n      \"accent\": {},\n      \"signal\": {},\n      \"guide\": {}\n    }}",
        paint_json(&palette.primary),
        paint_json(&palette.accent),
        paint_json(&palette.signal),
        paint_json(&palette.guide),
    )
}

fn paint_json(paint: &Paint) -> String {
    format!(
        "{{\"hex\": \"{}\", \"oklch\": [{}, {}, {}], \"contrast\": {}, \"target\": {}}}",
        paint.hex,
        format_number(paint.lightness),
        format_number(paint.chroma),
        format_number(paint.hue),
        format_number(paint.contrast),
        format_number(paint.target_contrast),
    )
}

fn format_number(value: f64) -> String {
    let normalized = if value.abs() < 0.000_000_5 {
        0.0
    } else {
        value
    };
    let mut rendered = format!("{normalized:.6}");
    while rendered.ends_with('0') {
        rendered.pop();
    }
    if rendered.ends_with('.') {
        rendered.pop();
    }
    rendered
}

#[cfg(test)]
mod tests {
    use super::append_glyph;
    use super::geometry_fragment;
    use super::tooth_path;
    use crate::model::GearModel;
    use crate::model::Spec;

    #[test]
    fn one_tooth_is_reused_at_exact_angular_pitch() {
        let model = GearModel::new(Spec::rings());
        assert!(model.is_ok());
        if let Ok(model) = model {
            let fragment = geometry_fragment(&model);
            assert_eq!(fragment.matches("<use href=\"#tooth\"").count(), 30);
            assert!(fragment.contains("transform=\"rotate(12)\""));
            assert!(!tooth_path(&model).contains("NaN"));
        }
    }

    #[test]
    fn glyph_is_one_outer_silhouette_with_one_counter() {
        let model = GearModel::new(Spec::rings());
        assert!(model.is_ok());
        if let Ok(model) = model {
            let mut rendered = String::new();
            append_glyph(&mut rendered, model.glyph());
            assert_eq!(rendered.matches("<path ").count(), 1);
            assert_eq!(rendered.matches(" Z").count(), 2);
            assert!(rendered.contains("fill-rule=\"evenodd\""));
        }
    }
}
